from __future__ import annotations
import hashlib,json
from pathlib import Path
from finance_query.research.vietnamese_percent_change_pre_unseen import validate_pre_unseen
def write(path:Path,value:dict)->str:path.write_text(json.dumps(value)+"\n");return hashlib.sha256(path.read_bytes()).hexdigest()
def test_receipt_hash_and_gate_validation(tmp_path:Path)->None:
    h=tmp_path/"h.json";d=tmp_path/"d.json";hh=write(h,{"decision_thresholds":{"minimum_newly_correct_development":2,"minimum_precision_on_predictions":1.0,"maximum_false_confident_candidate":0,"maximum_regressed_baseline_predictions":0}});dh=write(d,{"arms":{"B_A_plus_narrow_relative_percent_change_contract":{"precision_on_predictions":1.0,"false_confident_count":0}},"candidate_outcome_counts":{"IMPROVED":3}});r=tmp_path/"r.json";write(r,{"protocol":"vietnamese_percent_change_semantics_pre_unseen_freeze_v1","schema_version":1,"experiment_id":"vietnamese_percent_change_semantics_v1","inputs":{"hypothesis_freeze":{"path":str(h),"sha256":hh},"development_report":{"path":str(d),"sha256":dh}},"development_gate":{"status":"PASS","observed":{"newly_correct":3,"precision_on_predictions":1.0,"false_confident_candidate":0,"regressed_baseline_predictions":0}},"frozen_untouched_predictions":{"minimum_newly_correct_untouched":2,"minimum_precision_on_predictions":1.0,"maximum_false_confident_candidate":0,"maximum_regressed_baseline_predictions":0,"metric_holdout_prediction":{},"composition_holdout_prediction":{}},"untouched_evaluation_allowed":True,"full_vifinqa_dataset_allowed":False,"source_contract":{"research_only":True,"submission_eligible":False,"vifinqa_answer_authority":False}});assert validate_pre_unseen(r,tmp_path)["status"]=="PASS";d.write_text("{}\n");assert validate_pre_unseen(r,tmp_path)["status"]=="FAIL"
